"""One publishing vocabulary, always read from a recalculated workbook."""
from results import *
F='Funding Decision';ND='Normalized DCF';FI='Funding Inputs';PD='Peer Diagnostics';AF='FY Forecast'
def cash(x):return ('−' if x<-.5 else '')+'₹'+n(abs(x))+'cr'
def cv(sh,addr):return cash(v(sh,addr))
def num(sh,addr):return n(v(sh,addr))
def percent(sh,addr):return pct(v(sh,addr))
def outcome():return v(F,'B10')
def action():
    return {'RELEASE':'Release the scheduled tranche. Base and downside cash clear the planning floor.',
    'CONDITIONAL':'Condition release on a committed downside liquidity backstop.',
    'DELAY':'Move the tranche to the later payment dates and confirm the cash floor before release.',
    'FINANCE BEFORE RELEASE':'Hold the tranche until term funding and a downside liquidity backstop are committed.',
    'DEFER / RESIZE FUNDING':'Defer the tranche. The proposed term funding is insufficient; resize the program or secure more capital.'}[outcome()]
def short():return f"{outcome()} · {cv(F,'G4')} of {cv(FI,'B5')} self-funded"
def gate():return f"{action()} The on-time schedule first breaches the {cv(FI,'B4')} cash floor in {v(F,'B4')}. Peak bridge borrowing is {cv(F,'C4')}."
def funding_table():
    return [[v(F,'A'+str(r)),v(F,'B'+str(r)),cv(F,'C'+str(r)),cv(F,'H'+str(r)),cv(F,'E'+str(r)),cv(F,'F'+str(r)),cv(F,'G'+str(r))] for r in range(4,9)]
HEAD=['Case','First gap¹','Peak bridge','Peak loans²','Cash pre-bridge','Funded low','Affordable']
def dcf_story():
    return f"The normalized DCF gives {price(v(ND,'B36'))} per share versus the ₹3,545.80 close. It assumes a {percent(ND,'B38')} FY31 EBITDA margin, {cv(ND,'B37')} of FY31 unlevered free cash flow and {percent(ND,'B28')} terminal reinvestment."
def external():
    return f"The illustrative {cv(FI,'B28')} term issue leaves {cv(F,'E6')} at the base trough. Under funded stress, the plan needs another {cv(F,'C8')} of peak bridge capacity."
def sensitivities():
    return [[v(ND,'D'+str(r)),percent(ND,'E'+str(r)),percent(ND,'F'+str(r)),percent(ND,'G'+str(r)),price(v(ND,'H'+str(r)))] for r in range(25,33)]
def legacy():
    return f"The reference DCF gives {price(v(ND,'B48'))}. Reaching the close with its explicit flows fixed requires {cv(ND,'B50')} of FY31-equivalent UFCF versus {cv(ND,'B49')} modeled. At fixed sales, D&A, capex and working capital that implies a {percent(ND,'B51')} EBITDA margin against its 12.5% base. The reverse test changes the terminal run rate only."
def market():
    return f"On the revised sales and reinvestment path, a {v(ND,'B41')*10000:,.0f} bp margin uplift phased through FY31 produces a {percent(ND,'B42')} FY31 EBITDA margin, {cv(ND,'B43')} of FY31 UFCF and {price(v(ND,'B47'))} per share. FY32 reinvestment rises to {cv(ND,'B45')}."
def report(t):
    import re
    def section(no,body):
        nonlocal t
        t=re.sub(r'(?ms)(^## '+str(no)+r'\. [^\n]+\n).*?(?=^## \d+\.|\Z)',lambda x:x[1]+'\n'+body.strip()+'\n\n',t,count=1)
    section(1,f'**{short()}.** {gate()} {external()}\n\n{dcf_story()} FY26 peer EV/EBITDA implies {price(v(VS,"B6"))}–{price(v(VS,"D6"))}. See the dashboard, Funding Decision and Lineage. The model measures quarter-end liquidity from reported September balances. October through 6 November cash movements are unobservable.')
    section(10,dcf_story()+f' Explicit PV is {cv(ND,"B31")}; continuing PV is {cv(ND,"B32")}. Apply {percent(ND,"B24")} WACC to dated quarters. Allocate the December quarter evenly over 92 days and retain the days after 6 November. Terminal FY32 NOPAT of {cv(ND,"B27")} supports {percent(ND,"B25")} growth with {percent(ND,"B26")} incremental ROIC. Deduct {cv(ND,"B29")} reinvestment to obtain {cv(ND,"B30")} continuing UFCF. Deduct September claims of {cv(ND,"B34")}. FY29 trademark and replacement lease investment appear in operating valuation cash flow once.\n\n'+legacy()+f' The reference FY31 model had sales of {cv(DC,"F5")}, a {percent(DC,"F7")} EBITDA margin and cash capex of {cv(DC,"F12")}. The quarterly underwriting instead reaches {cv(AF,"F4")} sales, {percent(AF,"F35")} margin and {cv(AF,"F34")} cash investment. The resulting {cv(ND,"B37")} FY31 UFCF falls to {cv(ND,"B30")} in the normalized terminal year as reinvestment catches up. Moving to the new forecast changes explicit PV by ₹{num(ND,"B62")} per share and continuing PV by ₹{num(ND,"B63")} per share. Unit growth, price recovery, favorable mix and fixed-cost absorption expand margin; FY31 regular cash investment of {cv(AF,"F34")} is materially below the reference forecast. These are consequential underwriting judgments.\n\n'+market())
    section(11,f"Weekly stock beta is {v(WA,'B8'):.2f} on 52 raw price returns versus NIFTYBEES. The July India ERP is {percent(WA,'B9')}; subtract the July sovereign spread from the 6 November CCIL benchmark to get {percent(WA,'B7')} risk-free. Use market equity and gross financial debt including leases. Pretax debt cost is the top of the FY26 domestic loan range. Peer Diagnostics un-levers each peer beta at its gross debt / spot equity with a common normalized tax rate, takes the median {v(PD,'B18'):.2f}, and re-levers to CEAT at {v(PD,'B19'):.2f}. The resulting {percent(PD,'B20')} WACC gives {price(v(ND,'H26'))}. Retain stock beta for the central case because it directly observes CEAT's listed risk. Geographic mix, short sample and limited peer count weaken both estimates.")
    section(12,markdown_table(['Normalized sensitivity','WACC','Growth','Incremental ROIC','₹ / share'],sensitivities())+'\n\nEach line changes one input and recomputes both the explicit and continuing PV. Growth changes required terminal reinvestment. The original two-dimensional grids remain in the reference model.\n\n'+markdown_table(HEAD,funding_table())+'\n\n¹ First quarter below floor after planned financing, before a balancing draw. ² Gross borrowings exclude leases. Negative pre-bridge cash measures an unfunded requirement. Funded cash assumes the bridge is available. Stress adds an eight-point commodity step, lowers recovery to 40% and assumes 10% nonrenewal of residual debt. No additional borrowing capacity is evidenced.')
    section(13,dcf_story()+f' FY26 three-peer interquartile band is {price(v(VS,"B6"))}–{price(v(VS,"D6"))}. The FY26 median of {mult(v(TC,"C17"))} produces {price(v(VS,"C6"))}. Use this as an independent relative mark given the two-peer September LTM sample and CEAT-specific margin recovery. The two methods should remain separately interpretable.')
    section(15,gate()+' '+external()+f' Delaying the two payments by four quarters reduces peak bridge need to {cv(F,"C5")}. The core plan itself still breaches the floor. Before signing equipment orders require documented term availability, monthly cash forecasts clearing {cv(FI,"B4")}, and downside coverage. If either fails, hold the discretionary spend. Re-underwrite if the Q3 basket exceeds the 3–3.5% management outlook or collection/inventory days exceed the modeled path. These are analyst approval gates.\n\nManagement guided to ₹1,400cr standalone plus ₹100–150cr upstream CAMSO equipment. Midpoint group planning envelope ₹1,525cr includes ₹802cr already spent. The proposed tranche is incremental. March capital contracts outstanding were ₹1,785.12cr net of advances. September committed-scope phasing is an analyst estimate. Inventory commitment of about US$44m is included through turnover; any unpaid lump sum above modeled inventory would require additional funding. The separate US$44m trademark is scheduled in Q2 FY29.\n\n'+markdown_table(['On-time, ₹ crore']+[f'FY{y}E' for y in range(27,32)],metric_rows(AF,[('Sales',4,n),('Operating EBITDA',5,n),('Group PAT',12,n),('Operating cash',13,n),('Investing cash',14,n),('Financing cash',15,n),('Closing cash',16,n),('Borrowings',17,n),('Equity',26,n)],'BCDEF')))
    section(17,'There is one reportable group segment. CAMSO contributed ₹420.65cr of FY26 product sales after acquisition. Subtracting this from group operating revenue gives ₹15,257.35cr and a directional 15.4% growth proxy against FY25, compared with 18.6% reported. Product sales and total operating revenue have different perimeters. H1 disclosed end-customer billing and transition counts cannot establish audited consolidated CAMSO sales or margins. The core unit index, relative OHT realization, capacity, pass-through and CAMSO realization factor are assumptions. Forecast material cost uses a composite basket; rubber-specific spend is unavailable.\n\nQuarter-end observations can miss intraperiod stress. Contract phasing, lender headroom, security packages, refinancing terms, plant-level returns and a project-specific sales ramp are unverified. Existing short funding is assumed renewed except in stress. Forecast other assets/liabilities are held constant. A common margin shock increases EBITDA without fresh explicit capacity and maintains the terminal incremental ROIC; it is a market-implied diagnostic. Legacy DCF and sensitivities are retained for comparison. The annual statements contain rounded interim balances.\n\nIndependent public-information portfolio analysis. Source archive, publication dates, conversions and primary-page checks and derived component ties are in the input register.')
    # Add leave-one-out information directly to the existing comparable-company evidence.
    pos=t.index('## 10.')
    t=t[:pos]+f"Excluding MRF, Apollo or JK in turn gives {price(v(PD,'C14'))}, {price(v(PD,'C15'))} or {price(v(PD,'C16'))} per CEAT share. The wide dispersion supports using the median and publishing the interval. Comparable EBITDA removes other income from pre-exceptional PBT plus finance costs and depreciation. JK's ₹2,089cr PBDIT falls to ₹2,031cr. Compare closing-asset operating returns, margin, business mix and leverage in Peer Diagnostics.\n\n"+t[pos:]
    return t

